#[cfg(feature = "text_lookup_work_counter")]
use std::cell::Cell;

#[cfg(feature = "text_lookup_work_counter")]
thread_local! {
    static TEXT_LOOKUP_CHARS_WALKED: Cell<u64> = Cell::new(0);
}

#[cfg(feature = "text_lookup_work_counter")]
pub fn reset_text_lookup_chars_walked() {
    TEXT_LOOKUP_CHARS_WALKED.with(|c| c.set(0));
}

#[cfg(not(feature = "text_lookup_work_counter"))]
pub fn reset_text_lookup_chars_walked() {}

#[cfg(feature = "text_lookup_work_counter")]
pub fn take_text_lookup_chars_walked() -> u64 {
    TEXT_LOOKUP_CHARS_WALKED.with(|c| {
        let walked = c.get();
        c.set(0);
        walked
    })
}

#[cfg(not(feature = "text_lookup_work_counter"))]
pub fn take_text_lookup_chars_walked() -> u64 {
    0
}

#[cfg(feature = "text_lookup_work_counter")]
fn record_substring_chars_walked(s: &str, start: usize, take_len: usize) {
    let walked = if s.is_ascii() {
        take_len as u64
    } else {
        (start + take_len) as u64
    };
    TEXT_LOOKUP_CHARS_WALKED.with(|c| c.set(c.get() + walked));
}

#[cfg(not(feature = "text_lookup_work_counter"))]
fn record_substring_chars_walked(_s: &str, _start: usize, _take_len: usize) {}

#[cfg(feature = "text_lookup_work_counter")]
fn record_source_chars_slice_walked(units: u64) {
    TEXT_LOOKUP_CHARS_WALKED.with(|c| c.set(c.get() + units));
}

#[cfg(not(feature = "text_lookup_work_counter"))]
fn record_source_chars_slice_walked(_units: u64) {}

#[cfg(feature = "text_lookup_work_counter")]
pub fn record_source_chars_index_lookup() {
    TEXT_LOOKUP_CHARS_WALKED.with(|c| c.set(c.get() + 1));
}

#[cfg(not(feature = "text_lookup_work_counter"))]
pub fn record_source_chars_index_lookup() {}

pub trait V2Concat {
    fn v1_concat(self, other: Self) -> Self;
}

impl V2Concat for String {
    fn v1_concat(mut self, other: String) -> String {
        self.push_str(&other);
        self
    }
}

impl<T> V2Concat for Vec<T> {
    fn v1_concat(mut self, other: Vec<T>) -> Vec<T> {
        self.extend(other);
        self
    }
}

pub fn concat<T: V2Concat>(a: T, b: T) -> T {
    a.v1_concat(b)
}

pub fn char_at(s: &str, pos: i64) -> String {
    let pos = pos.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        if pos >= bytes.len() {
            return String::new();
        }
        return String::from(bytes[pos] as char);
    }
    s.chars()
        .nth(pos)
        .map(|ch| ch.to_string())
        .unwrap_or_default()
}

pub fn string_length(s: &str) -> i64 {
    if s.is_ascii() {
        s.len() as i64
    } else {
        s.chars().count() as i64
    }
}

pub fn substring(s: &str, start: i64, end: i64) -> String {
    let start = start.max(0) as usize;
    let end = end.max(0) as usize;
    if end <= start {
        return String::new();
    }
    if s.is_ascii() {
        let len = s.len();
        if start >= len {
            return String::new();
        }
        let out_end = end.min(len);
        let take_len = out_end.saturating_sub(start);
        record_substring_chars_walked(s, start, take_len);
        return s[start..out_end].to_string();
    }
    let take_len = end.saturating_sub(start);
    record_substring_chars_walked(s, start, take_len);
    s.chars().skip(start).take(take_len).collect()
}

pub fn string_contains(s: &str, sub: String) -> bool {
    s.contains(&*sub)
}

pub fn contains(s: String, sub: String) -> bool {
    string_contains(&s, sub)
}

