// -- Rc-wrapped container operations (FF-8) ---------------------------------
// These mirror the bare Vec/HashMap functions above but operate on Rc-wrapped
// containers for O(1) clone cost. Generated code using Rc container templates
// will call these. Read-only functions (map_get, map_keys, map_values, lookup,
// map_contains_key, map_has) work with Rc<HashMap> via auto-deref.

pub fn rc_list_push<T: Clone>(list: Rc<Vec<T>>, item: T) -> Rc<Vec<T>> {
    let mut v = list;
    Rc::make_mut(&mut v).push(item);
    v
}

pub fn rc_list_concat<T: Clone>(a: Rc<Vec<T>>, b: Rc<Vec<T>>) -> Rc<Vec<T>> {
    let mut result = a;
    Rc::make_mut(&mut result).extend(b.iter().cloned());
    result
}

pub fn rc_map_insert<K: std::cmp::Eq + std::hash::Hash + Clone, V: Clone>(
    map: Rc<HashMap<K, V>>,
    key: K,
    value: V,
) -> Rc<HashMap<K, V>> {
    let mut m = map;
    Rc::make_mut(&mut m).insert(key, value);
    m
}

pub fn rc_map_merge<K: std::cmp::Eq + std::hash::Hash + Clone, V: Clone>(
    base: Rc<HashMap<K, V>>,
    overlay: Rc<HashMap<K, V>>,
) -> Rc<HashMap<K, V>> {
    let mut result = base;
    let inner = Rc::make_mut(&mut result);
    for (k, v) in overlay.iter() {
        inner.insert(k.clone(), v.clone());
    }
    result
}

pub fn rc_index_by<V: Clone, F: Fn(&V) -> String>(
    list: Rc<Vec<V>>,
    key_fn: F,
) -> Rc<HashMap<String, V>> {
    Rc::new(list.iter().map(|v| (key_fn(v), v.clone())).collect())
}

pub fn rc_empty_map<K: std::cmp::Eq + std::hash::Hash, V>() -> Rc<HashMap<K, V>> {
    Rc::new(HashMap::new())
}

impl<T: Clone> V2Concat for Rc<Vec<T>> {
    fn v1_concat(self, other: Rc<Vec<T>>) -> Rc<Vec<T>> {
        rc_list_concat(self, other)
    }
}

pub fn scan_while(s: &str, start: i64, pred: impl Fn(String) -> bool) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let mut pos = start.min(bytes.len());
        while pos < bytes.len() && pred(String::from(bytes[pos] as char)) {
            pos += 1;
        }
        return pos as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    for ch in s.chars().skip(start) {
        if pred(ch.to_string()) {
            pos += 1;
        } else {
            break;
        }
    }
    pos as i64
}

pub fn skip_horizontal_ws(s: &str, start: i64) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let mut pos = start.min(bytes.len());
        while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t') {
            pos += 1;
        }
        return pos as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    for ch in s.chars().skip(start) {
        if ch == ' ' || ch == '\t' {
            pos += 1;
        } else {
            break;
        }
    }
    pos as i64
}

pub fn scan_to_eol(s: &str, start: i64) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let start = start.min(bytes.len());
        for i in start..bytes.len() {
            if bytes[i] == b'\n' {
                return i as i64;
            }
        }
        return bytes.len() as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    for ch in s.chars().skip(start) {
        if ch == '\n' {
            return pos as i64;
        }
        pos += 1;
    }
    pos as i64
}

pub fn scan_string_end(s: &str, start: i64) -> i64 {
    let start = start.max(0) as usize;
    if s.is_ascii() {
        let bytes = s.as_bytes();
        let mut pos = start.min(bytes.len());
        while pos < bytes.len() {
            if bytes[pos] == b'\\' {
                pos += 2;
            } else if bytes[pos] == b'\"' {
                return (pos + 1) as i64;
            } else {
                pos += 1;
            }
        }
        return bytes.len() as i64;
    }
    let char_len = s.chars().count();
    let start = start.min(char_len);
    let mut pos = start;
    let mut escaped = false;
    for ch in s.chars().skip(start) {
        if escaped {
            escaped = false;
            pos += 1;
        } else if ch == '\\' {
            escaped = true;
            pos += 1;
        } else if ch == '\"' {
            return (pos + 1) as i64;
        } else {
            pos += 1;
        }
    }
    pos as i64
}

pub fn code_point(c: String) -> i64 {
    c.chars().next().map(|ch| ch as i64).unwrap_or(0)
}

pub fn from_code_point(cp: i64) -> String {
    char::from_u32(cp as u32)
        .map(|c| c.to_string())
        .unwrap_or_default()
}

pub fn is_xid_start(cp: i64) -> bool {
    char::from_u32(cp as u32)
        .map(unicode_ident::is_xid_start)
        .unwrap_or(false)
}

pub fn is_xid_continue(cp: i64) -> bool {
    char::from_u32(cp as u32)
        .map(unicode_ident::is_xid_continue)
        .unwrap_or(false)
}

pub fn is_emoji_ident(cp: i64) -> bool {
    use unicode_properties::emoji::EmojiStatus;
    use unicode_properties::emoji::UnicodeEmoji;
    char::from_u32(cp as u32)
        .map(|c| {
            matches!(
                c.emoji_status(),
                EmojiStatus::EmojiPresentation
                    | EmojiStatus::EmojiPresentationAndModifierBase
                    | EmojiStatus::EmojiPresentationAndEmojiComponent
                    | EmojiStatus::EmojiPresentationAndModifierAndEmojiComponent
            ) && !unicode_ident::is_xid_continue(c)
        })
        .unwrap_or(false)
}

const FNV1A64_OFFSET: u64 = 0xcbf29ce484222325;
const FNV1A64_PRIME: u64 = 0x100000001b3;

fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut hash = FNV1A64_OFFSET;
    for b in bytes {
        hash ^= *b as u64;
        hash = hash.wrapping_mul(FNV1A64_PRIME);
    }
    hash
}

pub type Hash = String;

const HASH_DIGEST_LEN: usize = 16;

pub fn is_hash_digest(s: &str) -> bool {
    s.len() == HASH_DIGEST_LEN && s.bytes().all(|b| b.is_ascii_hexdigit())
}

fn expect_hash_digest(s: &str, arg: &str) {
    if !is_hash_digest(s) {
        panic!("{} must be a 16-char hex Hash digest", arg);
    }
}

/// Content hash over raw bytes — the byte-level single authority. `atom_identity_hash`
/// is the `String` projection of this. Use this directly for arbitrary binary content
/// (e.g. an executable or serialized payload): routing bytes through `String`/
/// `from_utf8_lossy` first collapses every invalid UTF-8 sequence to U+FFFD, so distinct
/// byte sequences would hash equal — a §5 silent-collision fail-open for content-addressing.
pub fn bytes_identity_hash(bytes: &[u8]) -> Hash {
    format!("{:016x}", fnv1a64(bytes))
}

pub fn atom_identity_hash(s: String) -> Hash {
    bytes_identity_hash(s.as_bytes())
}

pub fn hash_combine(a: Hash, b: Hash) -> Hash {
    expect_hash_digest(&a, "a");
    expect_hash_digest(&b, "b");
    let mut bytes = a.into_bytes();
    bytes.push(0);
    bytes.extend_from_slice(b.as_bytes());
    format!("{:016x}", fnv1a64(&bytes))
}

#[derive(Debug, Clone)]
pub struct FilesystemReadResult {
    pub content: String,
}

pub fn filesystem_read(path: String) -> FilesystemReadResult {
    let content =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("failed to read {}: {}", path, e));
    FilesystemReadResult { content }
}

fn int_relu(x: i64) -> i64 {
    if x > 0 {
        x
    } else {
        0
    }
}

pub fn simd_relu_mul_add_scalar(a: &[i64], b: &[i64], c: &[i64]) -> Vec<i64> {
    assert_eq!(a.len(), b.len());
    assert_eq!(b.len(), c.len());
    a.iter()
        .zip(b.iter())
        .zip(c.iter())
        .map(|((ai, bi), ci)| {
            let mul = ai * bi;
            int_relu(mul + ci)
        })
        .collect()
}

pub fn simd_relu_mul_add_fused(a: &[i64], b: &[i64], c: &[i64]) -> Vec<i64> {
    assert_eq!(a.len(), b.len());
    assert_eq!(b.len(), c.len());
    let mut out = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        let fused = a[i] * b[i] + c[i];
        out.push(int_relu(fused));
    }
    out
}
